$s=@'
param($Lanes)  # hashtable lane->array of "Tn - name (Phase)" 
'@
# kanban writer script
@'
param([string]$Inprog="",[string]$Review="",[string]$Done="")
$names=[ordered]@{T1="scaffold-and-harness (Phase 1)";T2="money (Phase 1)";T3="tabular-reader (Phase 2)";T4="transactions-loader (Phase 2)";T5="rules-loader-and-matching (Phase 2)";T6="dedupe-filter-aggregate (Phase 3)";T7="renderers (Phase 3)";T8="cli (Phase 4)";T9="acceptance-and-determinism (Phase 4)"}
$dep=@{T1=@();T2=@("T1");T3=@("T1");T4=@("T3");T5=@("T3");T6=@("T2","T4","T5");T7=@("T2","T6");T8=@("T7");T9=@("T8")}
$ip=$Inprog -split ","|?{$_}; $rv=$Review -split ","|?{$_}; $dn=$Done -split ","|?{$_}
$ts=(Get-Date).ToString("yyyy-MM-dd HH:mm")
$b=@();$r=@();$i=@();$v=@();$d=@()
foreach($k in $names.Keys){
 $line="- [ ] $k - $($names[$k])"
 if($dn -contains $k){$d+="- [x] $k - $($names[$k])"}
 elseif($rv -contains $k){$v+=$line}
 elseif($ip -contains $k){$i+="$line <!-- in_progress: $ts -->"}
 elseif((@($dep[$k]|?{$dn -notcontains $_})).Count -eq 0){$r+=$line}
 else{$b+=$line}
}
$out="# Kanban: csvledger`n`n## Backlog`n"+($b-join"`n")+"`n`n## Ready`n"+($r-join"`n")+"`n`n## In Progress`n"+($i-join"`n")+"`n`n## Blocked`n`n## In Review`n"+($v-join"`n")+"`n`n## Done`n"+($d-join"`n")+"`n`n## Validation Checklist`n- [ ] ``python -m pytest -q`` green`n- [ ] AC1-AC10 each have a passing ``test_acN_*`` test`n- [ ] No non-stdlib imports or float usage in ``csvledger/```n- [ ] Outputs byte-identical across two runs`n"
[IO.File]::WriteAllText("$PWD\docs\spec-001-feature\kanban.md",$out)
