"""Exact money arithmetic and formatting (spec D3)."""

import decimal
from decimal import ROUND_HALF_UP, Decimal

CTX = decimal.Context(
    prec=decimal.MAX_PREC,
    Emax=decimal.MAX_EMAX,
    Emin=decimal.MIN_EMIN,
    rounding=ROUND_HALF_UP,
)

_CENT = Decimal("0.01")


def add(a: Decimal, b: Decimal) -> Decimal:
    return CTX.add(a, b)


def total(values) -> Decimal:
    result = Decimal(0)
    for v in values:
        result = CTX.add(result, v)
    return result


def format_money(value: Decimal) -> str:
    q = CTX.quantize(value, _CENT)
    if q == 0:
        return "0.00"
    return format(q, "f")

import csv
import io

from csvledger.errors import LedgerError

_FIELD_LIMIT = 2**31 - 1


def read_table(path, required, error_code):
    """Return a list of (line_num, {column: value}) for the rows of a CSV file."""
    path = str(path)
    csv.field_size_limit(_FIELD_LIMIT)

    def fail(message):
        return LedgerError(error_code, f"{path}: {message}")

    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        raise fail("cannot read file") from None
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise fail("not valid UTF-8") from None

    reader = csv.reader(io.StringIO(text, newline=""))
    try:
        records = []
        while True:
            try:
                row = next(reader)
            except StopIteration:
                break
            records.append((reader.line_num, row))
    except csv.Error:
        raise LedgerError(
            error_code, f"{path}:{reader.line_num}: malformed CSV"
        ) from None

    if not records:
        raise fail("missing header")
    header = [cell.strip().lower() for cell in records[0][1]]
    seen = set()
    for name in header:
        if name in seen:
            raise fail(f"duplicate column '{name}'")
        seen.add(name)
    for name in required:
        if name not in seen:
            raise fail(f"missing column '{name}'")

    rows = []
    for line_num, row in records[1:]:
        if len(row) == 0:
            continue
        if len(row) != len(header):
            raise LedgerError(
                error_code,
                f"{path}:{line_num}: expected {len(header)} fields, got {len(row)}",
            )
        rows.append((line_num, dict(zip(header, row))))
    return rows

import csv

import pytest

from csvledger import tabular
from csvledger.errors import LedgerError
from csvledger.tabular import read_table

REQ = ["date", "description", "amount"]


def load(tmp_path, data, required=REQ, code=3):
    p = tmp_path / "f.csv"
    p.write_bytes(data.encode("utf-8") if isinstance(data, str) else data)
    return read_table(str(p), required, code), str(p)


def err(tmp_path, data, required=REQ, code=3):
    p = tmp_path / "f.csv"
    p.write_bytes(data.encode("utf-8") if isinstance(data, str) else data)
    with pytest.raises(LedgerError) as ei:
        read_table(str(p), required, code)
    assert ei.value.exit_code == code
    return ei.value.message.replace(str(p), "<p>")


@pytest.mark.parametrize("code", [3, 4])
def test_zero_bytes(tmp_path, code):
    assert err(tmp_path, b"", code=code) == "<p>: missing header"


def test_bom_only(tmp_path):
    assert err(tmp_path, b"\xef\xbb\xbf") == "<p>: missing header"


def test_double_bom(tmp_path):
    data = b"\xef\xbb\xbf\xef\xbb\xbfdate,description,amount\n"
    assert err(tmp_path, data) == "<p>: missing column 'date'"


def test_blank_first_line(tmp_path):
    assert err(tmp_path, "\ndate,description,amount\n") == "<p>: missing column 'date'"


def test_header_only(tmp_path):
    rows, _ = load(tmp_path, "date,description,amount\n")
    assert rows == []


def test_bom_and_values_unstripped_extra_columns(tmp_path):
    rows, _ = load(tmp_path, b"\xef\xbb\xbf Amount ,DATE,x,description\n 1 ,d,e,f\n")
    assert rows == [(2, {"amount": " 1 ", "date": "d", "x": "e", "description": "f"})]


def test_blank_lines_skipped_but_counted(tmp_path):
    rows, _ = load(tmp_path, "date,description,amount\n\na,b,c\n\n\nd,e,f\n")
    assert [n for n, _ in rows] == [3, 6]


def test_whitespace_only_line_is_one_field(tmp_path):
    msg = err(tmp_path, "date,description,amount\n   \n")
    assert msg == "<p>:2: expected 3 fields, got 1"


def test_field_count_too_many(tmp_path):
    assert err(tmp_path, "a,b\n1,2,3\n", ["a", "b"], 4) == "<p>:2: expected 2 fields, got 3"


def test_multiline_quoted_line_num(tmp_path):
    rows, _ = load(tmp_path, 'date,description,amount\n1,"a\nb\nc",3\n4,5,6\n')
    assert [n for n, _ in rows] == [4, 5]
    assert rows[0][1]["description"] == "a\nb\nc"
    msg = err(tmp_path, 'date,description,amount\n1,"a\nb",3,4\n')
    assert msg == "<p>:3: expected 3 fields, got 4"


def test_invalid_utf8_beats_row_error(tmp_path):
    data = b"date,description,amount\n1,2\n\xff\xfe,x,y\n"
    assert err(tmp_path, data) == "<p>: not valid UTF-8"
    assert err(tmp_path, data, code=4) == "<p>: not valid UTF-8"


def test_directory_path(tmp_path):
    with pytest.raises(LedgerError) as ei:
        read_table(str(tmp_path), REQ, 3)
    assert ei.value.exit_code == 3
    assert ei.value.message == f"{tmp_path}: cannot read file"


def test_missing_file(tmp_path):
    p = str(tmp_path / "nope.csv")
    with pytest.raises(LedgerError) as ei:
        read_table(p, REQ, 4)
    assert (ei.value.exit_code, ei.value.message) == (4, f"{p}: cannot read file")


def test_duplicate_after_strip_lower(tmp_path):
    assert err(tmp_path, "Date , date,description,amount\n") == "<p>: duplicate column 'date'"


def test_first_duplicate_reported(tmp_path):
    assert err(tmp_path, "a,b,b,a\n", ["a", "b"]) == "<p>: duplicate column 'b'"


def test_duplicate_beats_missing(tmp_path):
    assert err(tmp_path, "a,a\n", ["a", "z"]) == "<p>: duplicate column 'a'"


def test_missing_first_in_listed_order(tmp_path):
    assert err(tmp_path, "amount\n") == "<p>: missing column 'date'"
    assert err(tmp_path, "date,amount\n") == "<p>: missing column 'description'"


def test_malformed_csv_via_field_limit(tmp_path, monkeypatch):
    monkeypatch.setattr(tabular, "_FIELD_LIMIT", 5)
    try:
        msg = err(tmp_path, "date,description,amount\n1,abcdefghij,3\n", code=4)
    finally:
        csv.field_size_limit(2**31 - 1)
    assert msg == "<p>:2: malformed CSV"


def test_field_limit_reset_each_call(tmp_path):
    csv.field_size_limit(5)
    rows, _ = load(tmp_path, "date,description,amount\n1,abcdefghij,3\n")
    assert len(rows) == 1
    assert csv.field_size_limit() == 2**31 - 1

import re
import sys
from dataclasses import dataclass
from typing import Optional

from csvledger.errors import RULES_ERROR, LedgerError
from csvledger.tabular import read_table

if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

_PRIORITY = re.compile(r"-?[0-9]+")


@dataclass(frozen=True)
class Rule:
    category: str
    type: str
    pattern: str
    priority: int
    compiled: Optional[re.Pattern] = None


def load_rules(path):
    path = str(path)
    rules = []
    for line, row in read_table(
        path, ("category", "type", "pattern", "priority"), RULES_ERROR
    ):

        def fail(msg):
            return LedgerError(RULES_ERROR, f"{path}:{line}: {msg}")

        category = row["category"].strip()
        if not category:
            raise fail("empty category")
        rtype = row["type"].strip()
        if rtype not in ("contains", "regex"):
            raise fail(f"invalid type '{rtype}'")
        pattern = row["pattern"].strip()
        if not pattern:
            raise fail("empty pattern")
        prio = row["priority"].strip()
        if not _PRIORITY.fullmatch(prio):
            raise fail(f"invalid priority '{prio}'")
        compiled = None
        if rtype == "regex":
            try:
                compiled = re.compile(pattern, re.IGNORECASE)
            except (re.error, RecursionError, OverflowError):
                raise fail(f"invalid regex '{pattern}'") from None
        rules.append(Rule(category, rtype, pattern, int(prio), compiled))
    return rules


def categorize(description, rules):
    best = None
    folded = None
    for rule in rules:
        if best is not None and rule.priority <= best.priority:
            continue
        if rule.type == "contains":
            if folded is None:
                folded = description.casefold()
            hit = rule.pattern.casefold() in folded
        else:
            hit = rule.compiled.search(description) is not None
        if hit:
            best = rule
    return best.category if best else "Uncategorized"

"""Transaction CSV loader (contract: Transaction CSV; spec D2)."""

import datetime
import re
from dataclasses import dataclass
from decimal import Decimal

from csvledger.errors import TX_ERROR, LedgerError
from csvledger.tabular import read_table

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"-?[0-9]+(\.[0-9]+)?")


@dataclass(frozen=True)
class Transaction:
    date: str
    description: str
    amount: Decimal

    @property
    def month(self) -> str:
        return self.date[:7]


def _valid_date(value):
    if not _DATE_RE.fullmatch(value):
        return False
    try:
        datetime.date(int(value[:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        return False
    return True


def load_transactions(path):
    path = str(path)
    result = []
    for line_num, row in read_table(path, ("date", "description", "amount"), TX_ERROR):
        date = row["date"].strip()
        if not _valid_date(date):
            raise LedgerError(TX_ERROR, f"{path}:{line_num}: invalid date '{date}'")
        amount = row["amount"].strip()
        if not _AMOUNT_RE.fullmatch(amount):
            raise LedgerError(TX_ERROR, f"{path}:{line_num}: invalid amount '{amount}'")
        result.append(Transaction(date, row["description"].strip(), Decimal(amount)))
    return result

"""Dedupe and month filtering (contract R5, R8; spec D11)."""


def dedupe(txs):
    """Return (kept, n_dupes); key is (date, description, amount), first wins."""
    seen = set()
    kept = []
    for tx in txs:
        key = (tx.date, tx.description, tx.amount)
        if key in seen:
            continue
        seen.add(key)
        kept.append(tx)
    return kept, len(txs) - len(kept)


def filter_month(txs, month):
    """Keep transactions whose date[:7] equals month; None keeps all."""
    if month is None:
        return list(txs)
    return [tx for tx in txs if tx.date[:7] == month]

