"""Table and JSON renderers (contract R9, R11; spec D8). Pure functions."""

import json
import unicodedata

from csvledger.money import format_money


def _clean(cell):
    return "".join(" " if unicodedata.category(c) == "Cc" else c for c in cell)


def _table(headers, aligns, rows):
    rows = [[_clean(c) for c in row] for row in rows]
    widths = [
        max([len(h)] + [len(r[i]) for r in rows]) for i, h in enumerate(headers)
    ]

    def line(cells):
        parts = [
            c.rjust(w) if a == "r" else c.ljust(w)
            for c, w, a in zip(cells, widths, aligns)
        ]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in rows)
    return "".join(out)


def _dump(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def render_report_table(rows):
    body = [
        [
            m.month,
            c.category,
            str(c.count),
            format_money(c.income),
            format_money(c.expenses),
            format_money(c.net),
        ]
        for m in rows
        for c in m.categories
    ]
    return _table(
        ["MONTH", "CATEGORY", "COUNT", "INCOME", "EXPENSES", "NET"],
        "llrrrr",
        body,
    )


def render_report_json(rows):
    return _dump(
        {
            "months": [
                {
                    "month": m.month,
                    "count": m.count,
                    "income": format_money(m.income),
                    "expenses": format_money(m.expenses),
                    "net": format_money(m.net),
                    "categories": [
                        {
                            "category": c.category,
                            "count": c.count,
                            "income": format_money(c.income),
                            "expenses": format_money(c.expenses),
                            "net": format_money(c.net),
                        }
                        for c in m.categories
                    ],
                }
                for m in rows
            ]
        }
    )


def render_categorize_table(pairs):
    body = [
        [tx.date, format_money(tx.amount), cat, tx.description] for tx, cat in pairs
    ]
    return _table(["DATE", "AMOUNT", "CATEGORY", "DESCRIPTION"], "lrll", body)


def render_categorize_json(pairs):
    return _dump(
        {
            "transactions": [
                {
                    "date": tx.date,
                    "description": tx.description,
                    "amount": format_money(tx.amount),
                    "category": cat,
                }
                for tx, cat in pairs
            ]
        }
    )

